#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct ExecutionContextCreatedEvent {
    /// A newly created execution context.
    #[serde(rename = "context")]
    pub context: ExecutionContextDescription,
}

impl crate::Event for ExecutionContextCreatedEvent {
    const NAME: &'static str = "Runtime.executionContextCreated";
}

/// Payload of the `Runtime.executionContextDestroyed` event.
///
/// Issued when execution context is destroyed.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct ExecutionContextDestroyedEvent {
    /// Id of the destroyed context
    ///
    /// **Deprecated.**
    #[serde(rename = "executionContextId")]
    pub execution_context_id: ExecutionContextId,
    /// Unique Id of the destroyed context
    ///
    /// **Experimental.**
    #[serde(rename = "executionContextUniqueId")]
    pub execution_context_unique_id: String,
}

impl crate::Event for ExecutionContextDestroyedEvent {
    const NAME: &'static str = "Runtime.executionContextDestroyed";
}

/// Payload of the `Runtime.executionContextsCleared` event.
///
/// Issued when all executionContexts were cleared in browser
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct ExecutionContextsClearedEvent {}

impl crate::Event for ExecutionContextsClearedEvent {
    const NAME: &'static str = "Runtime.executionContextsCleared";
}

/// Payload of the `Runtime.inspectRequested` event.
///
/// Issued when object should be inspected (for example, as a result of inspect() command line API
/// call).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct InspectRequestedEvent {
    #[serde(rename = "object")]
    pub object: RemoteObject,
    #[serde(rename = "hints")]
    pub hints: serde_json::Value,
    /// Identifier of the context where the call was made.
    ///
    /// **Experimental.**
    #[serde(
        rename = "executionContextId",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub execution_context_id: Option<ExecutionContextId>,
}

impl crate::Event for InspectRequestedEvent {
    const NAME: &'static str = "Runtime.inspectRequested";
}

